package com.mytraining;
import android.app.*;import android.content.*;import android.os.*;import android.media.RingtoneManager;
public class RestReceiver extends BroadcastReceiver {public void onReceive(Context c,Intent i){NotificationManager n=(NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE);if(Build.VERSION.SDK_INT>=26){NotificationChannel ch=new NotificationChannel("rest","Recupero",NotificationManager.IMPORTANCE_HIGH);ch.enableVibration(true);n.createNotificationChannel(ch);}Notification.Builder b=Build.VERSION.SDK_INT>=26?new Notification.Builder(c,"rest"):new Notification.Builder(c);b.setSmallIcon(android.R.drawable.ic_lock_idle_alarm).setContentTitle("Recupero terminato").setContentText(i.getStringExtra("name")).setAutoCancel(true).setDefaults(Notification.DEFAULT_ALL);b.setContentIntent(PendingIntent.getActivity(c,2,new Intent(c,MainActivity.class),PendingIntent.FLAG_IMMUTABLE));n.notify(1,b.build());}}